'use client';

import { useEffect, useId, useRef, useState } from 'react';
import { focusMenuItem, handleMenuKeys } from './menu-keys';
import { useDismiss } from './use-dismiss';
import './nested-menu-drilldown.css';

export interface MenuNode {
  id: string;
  label: string;
  children?: MenuNode[];
}

export interface NestedMenuDrilldownProps {
  /** Text on the opening button; also the name of the top level. */
  label: string;
  items: MenuNode[];
  /** Called with the labels from the top level down to the chosen item. */
  onSelect: (path: string[]) => void;
  className?: string;
}

/**
 * A menu whose submenus slide into the same panel instead of popping out
 * sideways. A back item and a visible path show where you are. Right arrow
 * or Enter opens a submenu, Left arrow or Escape goes back up (focusing the
 * item you came from), and Escape at the top closes the menu.
 */
export function NestedMenuDrilldown({
  label,
  items,
  onSelect,
  className = '',
}: NestedMenuDrilldownProps) {
  const [open, setOpen] = useState(false);
  const [path, setPath] = useState<MenuNode[]>([]);
  const [direction, setDirection] = useState<'in' | 'out'>('in');
  const root = useRef<HTMLDivElement>(null);
  const trigger = useRef<HTMLButtonElement>(null);
  const panel = useRef<HTMLDivElement>(null);
  const returnTo = useRef<string | null>(null);
  const id = useId();

  const level = path.length ? (path[path.length - 1].children ?? []) : items;

  useEffect(() => {
    if (!open) return;
    const back = returnTo.current;
    returnTo.current = null;
    const target = back
      ? panel.current?.querySelector<HTMLElement>(`[data-id="${back}"]`)
      : null;
    // Land on the item you came from, or on the level's first real item.
    const first = panel.current?.querySelector<HTMLElement>('.mg-drill__item');
    if (target) target.focus();
    else if (first) first.focus();
    else focusMenuItem(panel.current);
  }, [open, path]);

  const close = (refocus: boolean) => {
    setOpen(false);
    setPath([]);
    if (refocus) trigger.current?.focus();
  };
  const goUp = () => {
    if (!path.length) return close(true);
    returnTo.current = path[path.length - 1].id;
    setDirection('out');
    setPath((p) => p.slice(0, -1));
  };
  const enter = (node: MenuNode) => {
    setDirection('in');
    setPath((p) => [...p, node]);
  };
  useDismiss(open, [root], (reason) =>
    reason === 'escape' ? goUp() : close(false)
  );

  return (
    <div ref={root} className={`mg-drill ${className}`}>
      <button
        ref={trigger}
        type='button'
        className='mg-drill__trigger'
        aria-haspopup='menu'
        aria-expanded={open}
        aria-controls={id}
        onClick={() => (open ? close(false) : setOpen(true))}
      >
        {label} <span aria-hidden='true'>▾</span>
      </button>
      {open ? (
        <div className='mg-drill__surface'>
          <p className='mg-drill__path' aria-hidden='true'>
            {[label, ...path.map((p) => p.label)].join(' › ')}
          </p>
          <div
            key={path.map((p) => p.id).join('/') || 'root'}
            ref={panel}
            id={id}
            role='menu'
            aria-label={path.length ? path[path.length - 1].label : label}
            className='mg-drill__panel'
            data-direction={direction}
            onKeyDown={(event) => {
              if (event.key === 'ArrowLeft' && path.length) {
                event.preventDefault();
                goUp();
              } else if (event.key === 'Tab') close(false);
              else handleMenuKeys(event, panel.current);
            }}
          >
            {path.length ? (
              <button
                type='button'
                role='menuitem'
                tabIndex={-1}
                className='mg-drill__back'
                onClick={goUp}
              >
                ‹ Back to{' '}
                {path.length > 1 ? path[path.length - 2].label : label}
              </button>
            ) : null}
            {level.map((node) => (
              <button
                key={node.id}
                type='button'
                role='menuitem'
                tabIndex={-1}
                data-id={node.id}
                aria-haspopup={node.children ? 'menu' : undefined}
                className='mg-drill__item'
                onKeyDown={(event) => {
                  if (event.key === 'ArrowRight' && node.children) {
                    event.preventDefault();
                    enter(node);
                  }
                }}
                onClick={() => {
                  if (node.children) enter(node);
                  else {
                    onSelect([...path.map((p) => p.label), node.label]);
                    close(true);
                  }
                }}
              >
                <span>{node.label}</span>
                {node.children ? <span aria-hidden='true'>›</span> : null}
              </button>
            ))}
          </div>
        </div>
      ) : null}
    </div>
  );
}

.mg-drill {
  position: relative;
  display: inline-block;
  color: var(--mg-text, #ffffff);
}

.mg-drill__trigger {
  min-height: 44px;
  padding: 0 14px;
  border: 1px solid var(--mg-line-strong, #474747);
  border-radius: 10px;
  background: #121212;
  color: inherit;
  font: inherit;
  font-weight: 600;
  cursor: pointer;
}

.mg-drill__trigger:focus-visible {
  outline: 3px solid var(--mg-accent-text, #648aff);
  outline-offset: 2px;
}

.mg-drill__surface {
  position: absolute;
  top: calc(100% + 6px);
  left: 0;
  z-index: 10;
  width: 230px;
  overflow: hidden;
  border: 1px solid var(--mg-line, #303030);
  border-radius: 12px;
  background: #121212;
  box-shadow: 0 18px 34px -16px rgba(0, 0, 0, 0.5);
}

.mg-drill__path {
  margin: 0;
  padding: 8px 12px;
  border-bottom: 1px solid var(--mg-line, #303030);
  color: #b8b8b8;
  font-size: 12px;
}

.mg-drill__panel {
  display: grid;
  padding: 5px;
}

.mg-drill__panel[data-direction='in'] {
  animation: mg-drill-in 220ms cubic-bezier(0.2, 0.8, 0.2, 1);
}

.mg-drill__panel[data-direction='out'] {
  animation: mg-drill-out 220ms cubic-bezier(0.2, 0.8, 0.2, 1);
}

.mg-drill__item,
.mg-drill__back {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 40px;
  padding: 0 10px;
  border: 0;
  border-radius: 6px;
  background: none;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.mg-drill__back {
  color: var(--mg-accent-text, #648aff);
  font-weight: 600;
}

.mg-drill__item:hover,
.mg-drill__item:focus,
.mg-drill__back:hover,
.mg-drill__back:focus {
  outline: none;
  background: #141d38;
}

.mg-drill__item:focus-visible,
.mg-drill__back:focus-visible {
  box-shadow: inset 0 0 0 2px var(--mg-accent-text, #648aff);
}

@keyframes mg-drill-in {
  from {
    opacity: 0;
    transform: translateX(40px);
  }
}

@keyframes mg-drill-out {
  from {
    opacity: 0;
    transform: translateX(-40px);
  }
}

@media (prefers-reduced-motion: reduce) {
  .mg-drill__panel[data-direction] {
    animation: none;
  }
}

const ITEM =
  '[role="menuitem"]:not([aria-disabled="true"]), [role="menuitemradio"], [role="menuitemcheckbox"]';

function items(menu: HTMLElement) {
  return Array.from(menu.querySelectorAll<HTMLElement>(ITEM)).filter(
    (item) => item.closest('[role="menu"]') === menu
  );
}

/** Moves focus to the first (or last) item of `menu`. */
export function focusMenuItem(
  menu: HTMLElement | null,
  which: 'first' | 'last' = 'first'
) {
  if (!menu) return;
  const list = items(menu);
  list[which === 'first' ? 0 : list.length - 1]?.focus();
}

/**
 * Arrow, Home and End navigation between the items of `menu`. Call it from
 * the menu's keydown handler. Returns true when the key was handled.
 */
export function handleMenuKeys(
  event: { key: string; preventDefault(): void },
  menu: HTMLElement | null
): boolean {
  if (!menu) return false;
  const list = items(menu);
  if (list.length === 0) return false;
  const index = list.indexOf(document.activeElement as HTMLElement);
  let next: number;
  switch (event.key) {
    case 'ArrowDown':
      next = (index + 1) % list.length;
      break;
    case 'ArrowUp':
      next = index <= 0 ? list.length - 1 : index - 1;
      break;
    case 'Home':
      next = 0;
      break;
    case 'End':
      next = list.length - 1;
      break;
    default:
      return false;
  }
  event.preventDefault();
  list[next].focus();
  return true;
}

'use client';

import { useEffect, useRef, type RefObject } from 'react';

export type DismissReason = 'escape' | 'outside';

/**
 * While `active`, calls `onDismiss` when Escape is pressed or when a pointer
 * goes down outside every element in `refs`. Decide where focus goes in
 * `onDismiss`: back to the trigger after Escape, left alone after an
 * outside press.
 */
export function useDismiss(
  active: boolean,
  refs: RefObject<HTMLElement | null>[],
  onDismiss: (reason: DismissReason) => void
) {
  const callback = useRef(onDismiss);
  callback.current = onDismiss;
  const inside = useRef(refs);
  inside.current = refs;

  useEffect(() => {
    if (!active) return;
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key !== 'Escape') return;
      event.preventDefault();
      callback.current('escape');
    };
    const onPointerDown = (event: PointerEvent) => {
      const target = event.target as Node;
      if (inside.current.some((ref) => ref.current?.contains(target))) return;
      callback.current('outside');
    };
    document.addEventListener('keydown', onKeyDown);
    document.addEventListener('pointerdown', onPointerDown);
    return () => {
      document.removeEventListener('keydown', onKeyDown);
      document.removeEventListener('pointerdown', onPointerDown);
    };
  }, [active]);
}
